const c=document.querySelector('#neural');if(c){const ctx=c.getContext('2d');let w,h,dpr;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const pts=Array.from({length:230},(_,i)=>{let y=1-2*(i+.5)/230,a=i*2.399963,r=Math.sqrt(1-y*y);return [Math.cos(a)*r,y,Math.sin(a)*r]});function resize(){w=c.clientWidth;h=c.clientHeight;dpr=Math.min(devicePixelRatio||1,3840/w,2160/h);c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}function draw(ms){let t=reduce?0:ms*.00022;ctx.clearRect(0,0,w,h);let cx=w*.74,cy=h*.49,R=Math.min(w*.32,h*.43);let g=ctx.createRadialGradient(cx,cy,0,cx,cy,R*1.6);g.addColorStop(0,'#163c63');g.addColorStop(.45,'#102647');g.addColorStop(1,'#080e20');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);for(let j=0;j<11;j++){ctx.beginPath();ctx.ellipse(cx,cy,R*(1.13+j*.045),R*(.23+j*.026),t*.3+j*.24,0,Math.PI*2);ctx.strokeStyle=`rgba(86,190,255,${.08+j*.012})`;ctx.stroke()}let p=pts.map(([x,y,z])=>{let a=x*Math.cos(t)-z*Math.sin(t),b=x*Math.sin(t)+z*Math.cos(t),s=1/(1.7-b*.42);return [cx+a*R*1.65*s,cy+y*R*1.65*s,b]});for(let i=0;i<p.length;i++){for(let j=i+1;j<p.length;j++){let a=p[i],b=p[j],dist=Math.hypot(a[0]-b[0],a[1]-b[1]);if(dist<R*.23&&Math.abs(a[2]-b[2])<.32){ctx.strokeStyle=`rgba(81,240,224,${.28*(1-dist/(R*.23))})`;ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke()}}}for(const [x,y,z] of p){ctx.fillStyle=z>0?'#8dffe8':'#3575aa';ctx.beginPath();ctx.arc(x,y,1.3+(z+1)*1.1,0,7);ctx.fill()}if(!reduce&&!document.hidden)requestAnimationFrame(draw)}resize();requestAnimationFrame(draw);window.addEventListener('resize',()=>{resize();if(reduce)draw(0)});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!reduce)requestAnimationFrame(draw)})}
